 static Mesh Kernel(){var vertices=new List<Vector3>();var normals=new List<Vector3>();var triangles=new List<int>();var centers=new[]{new Vector3(0,0,0),new Vector3(-.23f,.13f,.04f),new Vector3(.19f,.17f,.06f),new Vector3(.02f,-.15f,-.18f)};var sizes=new[]{new Vector3(.25f,.28f,.23f),new Vector3(.20f,.17f,.20f),new Vector3(.20f,.23f,.19f),new Vector3(.22f,.18f,.16f)};
 for(int k=0;k<4;k++){int start=vertices.Count;for(int y=0;y<=6;y++)for(int x=0;x<=10;x++){float a=y*Mathf.PI/6,b=x*Mathf.PI*2/10;var n=new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b));vertices.Add(centers[k]+Vector3.Scale(n,sizes[k]));normals.Add(new Vector3(n.x/sizes[k].x,n.y/sizes[k].y,n.z/sizes[k].z).normalized);}for(int y=0;y<6;y++)for(int x=0;x<10;x++){int i=start+y*11+x;foreach(var tr in new[]{new[]{i,i+1,i+11},new[]{i+1,i+12,i+11}})if(Vector3.Cross(vertices[tr[1]]-vertices[tr[0]],vertices[tr[2]]-vertices[tr[0]]).sqrMagnitude>1e-10f)triangles.AddRange(tr);}}
 float max=vertices.Max(v=>v.magnitude);for(int i=0;i<vertices.Count;i++)vertices[i]*=.5f/max;var mesh=new Mesh{name="Native irregular popcorn kernel"};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Dir+"/NativeKernel.asset");return mesh;}
