 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");string receipt=Q+"popcorn-installation.json";if(File.Exists(receipt))throw new Exception("Already installed");var setup=EditorSceneManager.GetSceneManagerSetup();try{var scene=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();var role=d.GetComponentsInChildren<Chapter45RoleAction>(true).Single(r=>r.role==Chapter45RoleAction.Role.PopcornThrower);if(role.heldProp.Find("ContentCycle16 generated popcorn container")!=null)throw new Exception("Already applied");var stateType=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("ApplyContent16")).First(t=>t!=null);var state=stateType.GetMethod("State",BindingFlags.Static|BindingFlags.NonPublic);string before=(string)state.Invoke(null,new object[]{scene});File.WriteAllText(Q+"popcorn-protected-before.txt",before);string backup=Q+"recovery/ShoeTower-before-popcorn.unity";if(File.Exists(backup))throw new Exception("Preserve backup");File.Copy(scene.path,backup,false);AssetDatabase.Refresh();
 string fbx=Dir+"/DetailedPopcorn.fbx";var importer=AssetImporter.GetAtPath(fbx) as ModelImporter;if(importer==null)throw new Exception("Delivery not copied");importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.animationType=ModelImporterAnimationType.None;importer.importAnimation=false;importer.isReadable=false;importer.SaveAndReimport();string tex=Dir+"/DetailedPopcorn_M0_0.png";var ti=AssetImporter.GetAtPath(tex) as TextureImporter;if(ti==null)throw new Exception("Base texture missing");ti.textureType=TextureImporterType.Default;ti.sRGBTexture=true;ti.maxTextureSize=1024;ti.mipmapEnabled=true;ti.textureCompression=TextureImporterCompression.Compressed;ti.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name="Android",overridden=true,maxTextureSize=512,format=TextureImporterFormat.ASTC_6x6,compressionQuality=50});ti.SaveAndReimport();var mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="TRELLIS popcorn carton generated color",enableInstancing=true};mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tex));mat.SetFloat("_Smoothness",.12f);AssetDatabase.CreateAsset(mat,Dir+"/DetailedPopcorn.mat");
 var holder=G(role.heldProp,"ContentCycle16 generated popcorn container");var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(fbx),holder);foreach(var r in model.GetComponentsInChildren<Renderer>(true)){r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;}var rs=model.GetComponentsInChildren<Renderer>(true);var bounds=rs[0].bounds;foreach(var r in rs.Skip(1))bounds.Encapsulate(r.bounds);if(Mathf.Abs(bounds.size.y-1)>.03f)throw new Exception("Unexpected import axes/scale");Badge(holder,d.GetComponentsInChildren<TMP_Text>(true).First(t=>t.font!=null).font);holder.localPosition=new Vector3(0,-.18f,0);holder.localScale=Vector3.one*.36f;role.heldProp.Find("Popcorn paper cup").gameObject.SetActive(false);
 var kernel=Kernel();int count=0;foreach(var t in role.heldProp.Cast<Transform>().Where(t=>t.name.StartsWith("Popcorn kernel "))){t.GetComponent<MeshFilter>().sharedMesh=kernel;t.localPosition+=Vector3.up*.07f;t.localRotation=Quaternion.Euler(count*37,count*79,count*23);count++;}if(count!=7)throw new Exception("Unexpected kernel count");if(EditorUtility.IsPersistent(role.projectileTemplate))throw new Exception("Shared projectile asset must not change");role.projectileTemplate.GetComponent<MeshFilter>().sharedMesh=kernel;if(holder.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("New collider");string after=(string)state.Invoke(null,new object[]{scene});File.WriteAllText(Q+"popcorn-protected-pending.txt",after);if(before!=after)throw new Exception("Game contract changed");EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");scene=EditorSceneManager.OpenScene(scene.path);after=(string)state.Invoke(null,new object[]{scene});File.WriteAllText(Q+"popcorn-protected-after.txt",after);if(before!=after)throw new Exception("Reopened contract changed");var report=new{saved=true,generated="Local TRELLIS2 512 shape and texture carton",nativeFinishing="Readable POP CORN paper caption over garbled generated lettering; shared irregular 400-triangle kernel replaces existing spheres",reused="Existing actor CH10, own rig, left-palm binding, 7 kernel slots, original projectile template/collider",cartonHeight=.36f,cartonTriangles=AssetDatabase.LoadAllAssetsAtPath(fbx).OfType<Mesh>().Sum(m=>(long)m.GetIndexCount(0)/3),kernelTriangles=kernel.triangles.Length/3,androidTexture="512 ASTC6x6 with mipmaps",newColliders=0,oldCupPreservedInactive=true,gameplayComponentsUnchanged=true,newPaidCalls=0,utc=DateTime.UtcNow};File.WriteAllText(receipt,Json(report));return report;}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}
